import heapq


def topo_order(nodes, edges):
    all_nodes = set(nodes)

    for a, b in edges:
        all_nodes.add(a)
        all_nodes.add(b)

    adjacency = {node: set() for node in all_nodes}
    indegree = {node: 0 for node in all_nodes}

    for a, b in edges:
        if b not in adjacency[a]:
            adjacency[a].add(b)
            indegree[b] += 1

    ready = [node for node in all_nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order = []

    while ready:
        node = heapq.heappop(ready)
        order.append(node)

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(ready, neighbor)

    if len(order) != len(all_nodes):
        raise ValueError("Graph contains a cycle")

    return order
